#include <bits/stdc++.h>using namespace std;#define int long long const int N = 1e5 + 10; struct BIT{    int n;    int t[N] ={};     int lowbit(int x){ return x & -x;}     void add(int x,int v){        while(x <= n){            t[x] += v;            x += lowbit(x);        }    }     int sum(int x){        int res = 0;        while(x > 0){            res += t[x];            x -= lowbit(x);        }        return res;    }     int query(int l,int r){        return sum(r) - sum(l - 1);    }}; int n,q;int row[N],col[N]; signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);     cin >> n >> q;     BIT X,Y;    X.n = Y.n = n;     while(q--){        int op;cin >> op;        if(op == 1){            int x,y;            cin >> x >> y;            row[x]++;            col[y]++;            if(row[x] == 1) X.add(x,1);            if(col[y] == 1) Y.add(y,1);        }        else if(op == 2){            int x,y;            cin >> x >> y;            row[x]--;            col[y]--;            if(row[x] == 0) X.add(x,-1);            if(col[y] == 0) Y.add(y,-1);        }        else{            int x1,y1,x2,y2;            cin >> x1 >> y1 >> x2 >> y2;             int r = X.query(x1,x2);            int c = Y.query(y1,y2);             if(r >= x2 - x1 + 1 || c >= y2 - y1 + 1){                cout << "Yes" << '\n';            } else{                cout << "No" << '\n';            }        }    }    return 0;}